using Microsoft.ML;
using Microsoft.ML.Data;

namespace ChurnPredictor;

public class ChurnModelService
{
    private readonly string _dataPath;
    private readonly string _modelPath;
    private readonly MLContext _mlContext;

    public ChurnModelService(string dataPath, string modelPath)
    {
        _dataPath = dataPath;
        _modelPath = modelPath;
        _mlContext = new MLContext(seed: 42);
    }

    public (double AUC, double F1) Train()
    {
        var data = _mlContext.Data.LoadFromTextFile<CustomerData>(
            _dataPath, hasHeader: true, separatorChar: ',');

        // Map "Yes"/"No" string to boolean Label column
        var lookupData = new[]
        {
            new { Churned = "Yes", Label = true },
            new { Churned = "No", Label = false }
        };
        var lookupCollection = _mlContext.Data.LoadFromEnumerable(lookupData);

        var pipeline = _mlContext.Transforms.Conversion.MapValue(
                outputColumnName: "Label",
                lookupMap: lookupCollection,
                keyColumn: lookupCollection.Schema["Churned"],
                valueColumn: lookupCollection.Schema["Label"],
                inputColumnName: nameof(CustomerData.Churned))
            .Append(_mlContext.Transforms.Categorical.OneHotEncoding(
                outputColumnName: "RegionEncoded",
                inputColumnName: nameof(CustomerData.Region)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                nameof(CustomerData.Age),
                nameof(CustomerData.Income),
                nameof(CustomerData.PurchaseHistory),
                "RegionEncoded"))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .Append(_mlContext.BinaryClassification.Trainers.FastTree(
                labelColumnName: "Label",
                featureColumnName: "Features",
                numberOfLeaves: 4,
                minimumExampleCountPerLeaf: 1,
                numberOfTrees: 10));

        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2);

        var model = pipeline.Fit(split.TrainSet);

        var predictions = model.Transform(split.TestSet);
        var metrics = _mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");

        Console.WriteLine($"AUC: {metrics.AreaUnderRocCurve:F4}");
        Console.WriteLine($"F1: {metrics.F1Score:F4}");

        _mlContext.Model.Save(model, data.Schema, _modelPath);
        Console.WriteLine($"Model saved to {_modelPath}");

        return (metrics.AreaUnderRocCurve, metrics.F1Score);
    }

    public ChurnPrediction Predict(CustomerData input)
    {
        ITransformer model;
        using (var stream = File.OpenRead(_modelPath))
        {
            model = _mlContext.Model.Load(stream, out _);
        }

        var engine = _mlContext.Model.CreatePredictionEngine<CustomerData, ChurnPrediction>(model);
        return engine.Predict(input);
    }
}

