using Microsoft.Extensions.ML;
using ChurnPredictor;

var builder = WebApplication.CreateBuilder(args);

var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "customers.csv");
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "ChurnModel.zip");

builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
    .FromFile(filePath: modelPath, watchForChanges: true);

var app = builder.Build();

app.MapGet("/", () => "Hello");

app.MapGet("/train", () =>
{
    var service = new ChurnModelService(dataPath, modelPath);
    var (auc, f1) = service.Train();
    return Results.Ok(new { AUC = auc, F1 = f1, Message = "Model trained and saved." });
});

app.MapPost("/predict", (CustomerData input, PredictionEnginePool<CustomerData, ChurnPrediction> pool) =>
{
    var prediction = pool.Predict(input);
    return Results.Ok(new
    {
        prediction.PredictedLabel,
        prediction.Probability,
        prediction.Score
    });
});

app.Run();

